except BillingError as e: print("over:",e.code)

# non-positive
for a in ["0","-1"]:
    try: refund_shipping(p(),Decimal(a),T0); print("FAIL")
    except BillingError as e: print("nonpos:",e.code)

# float
try: refund_shipping(p(),10.0,T0); print("FAIL")
except BillingError as e: print("float:",e.code)

# wrong status
try: refund_shipping(p(status="authorized"),Decimal("1"),T0); print("FAIL")
except BillingError as e: print("state:",e.code)

# approval
try: refund_shipping(p("1000.00"),Decimal("600.00"),T0); print("FAIL")
except BillingError as e: print("approval:",e.code)
